import bpy, os, json
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError('arquivo errado')
roots=[r'C:\mcp-blender']
keywords=('mapa_base','mapabase','cota','cotado','curva','altim','mdt','dem','terrain','terreno','topo','contour','elev')
exts=('.shp','.dbf','.shx','.prj','.gpkg','.geojson','.json','.csv','.xyz','.txt','.tif','.tiff','.asc','.las','.laz','.zip','.7z','.osm','.xml')
found=[]
for root in roots:
 for dirpath,dirnames,filenames in os.walk(root):
  rel=os.path.relpath(dirpath,root); depth=0 if rel=='.' else rel.count(os.sep)+1
  if depth>7:
   dirnames[:]=[]; continue
  lowdir=dirpath.lower()
  for fn in filenames:
   low=fn.lower(); path=os.path.join(dirpath,fn); hit=any(k in low or k in lowdir for k in keywords) or low.endswith(exts)
   if not hit: continue
   try: size=os.path.getsize(path)
   except: size=None
   found.append({'path':path,'size':size,'ext':os.path.splitext(fn)[1].lower()})
found=sorted(found,key=lambda x:x['path'].lower())
terrain=bpy.data.objects.get('WORLD | TERRENO MASTER | blockout')
props={}
if terrain:
 for k in terrain.keys():
  try: props[k]=str(terrain[k])
  except: pass
meshprops={}
if terrain and terrain.data:
 for k in terrain.data.keys():
  try: meshprops[k]=str(terrain.data[k])
  except: pass
print('LOCAL_TERRAIN_SOURCE_INVENTORY_BEGIN'); print(json.dumps({'count':len(found),'files':found[:300],'terrain_object_props':props,'terrain_mesh_props':meshprops},ensure_ascii=False,separators=(',',':'))); print('LOCAL_TERRAIN_SOURCE_INVENTORY_END')
